import {surfaceMaps} from './visual-assets.js';
import {THREE,mat,mesh,canvasTexture,seeded} from './kit.js';
export function buildPitchSurface(root,turf){
 const random=seeded(1880),fibres=canvasTexture(512,512,(c,w,h)=>{c.fillStyle='#888';c.fillRect(0,0,w,h);for(let i=0;i<52000;i++){const x=random()*w,y=random()*h,l=1+random()*6;c.strokeStyle=random()>.5?'#b6b6b6':'#5d5d5d';c.lineWidth=.4+random()*.55;c.beginPath();c.moveTo(x,y);c.lineTo(x+.8,y+l);c.stroke();}});fibres.wrapS=fibres.wrapT=THREE.RepeatWrapping;fibres.repeat.set(24,37);fibres.anisotropy=8;turf.anisotropy=8;
 const groundMaterial=mat(0xffffff,{map:turf,bumpMap:fibres,bumpScale:.012,roughness:.94,...surfaceMaps('grass',{channel:1,repeat:[.28,.28],strength:.18})});
 const ground=mesh(new THREE.PlaneGeometry(72,111),groundMaterial,root,0,.005,0);ground.rotation.x=-Math.PI/2;ground.name='Mown grass with painted pitch markings';
 // Only a small patch around a ground-level visitor has actual blades. The
 // distant field uses the same colour map, with no stadium-wide grass mesh.
 const blade=new THREE.InstancedBufferGeometry();blade.setAttribute('position',new THREE.Float32BufferAttribute([-.004,0,0,.004,0,0,-.002,.021,.002,.002,.021,.002,0,.036,.005],3));blade.setAttribute('normal',new THREE.Float32BufferAttribute([0,.5,1,0,.5,1,0,.6,1,0,.6,1,0,.8,1],3));blade.setAttribute('uv',new THREE.Float32BufferAttribute([0,0,1,0,0,.6,1,.6,.5,1],2));blade.setIndex([0,1,2,1,3,2,2,3,4]);
 const count=26000,offsets=new Float32Array(count*3);for(let i=0;i<count;i++){offsets[i*3]=(random()-.5)*8;offsets[i*3+1]=(random()-.5)*8;offsets[i*3+2]=random()*Math.PI*2;}blade.setAttribute('bladeOffset',new THREE.InstancedBufferAttribute(offsets,3));blade.instanceCount=16000;
 const center={value:new THREE.Vector2()},material=mat(0xffffff,{map:turf,roughness:1,side:THREE.DoubleSide});material.onBeforeCompile=shader=>{shader.uniforms.bladeCenter=center;shader.vertexShader='attribute vec3 bladeOffset;uniform vec2 bladeCenter;varying float bladeFade;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>',`#include <begin_vertex>
float c=cos(bladeOffset.z),s=sin(bladeOffset.z);vec2 p=vec2(c*position.x-s*position.z,s*position.x+c*position.z)+bladeOffset.xy+bladeCenter;
transformed=vec3(p.x,position.y+.008,p.y);vMapUv=vec2(p.x/72.+.5,.5-p.y/111.);bladeFade=1.-smoothstep(2.2,3.8,length(bladeOffset.xy));`);shader.fragmentShader='varying float bladeFade;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <clipping_planes_fragment>','#include <clipping_planes_fragment>\nif(vMapUv.x<.006||vMapUv.x>.994||vMapUv.y<.006||vMapUv.y>.994||bladeFade<.15)discard;');};material.customProgramCacheKey=()=> 'local-grass-fibres-v1';const tufts=mesh(blade,material,root);tufts.name='Nearby turf blades';tufts.frustumCulled=false;
 return{ground,update(camera,high=false,low=false){tufts.visible=!low&&camera.position.y<5&&camera.position.y>.3&&Math.abs(camera.position.x)<43&&Math.abs(camera.position.z)<62;blade.instanceCount=high?26000:16000;center.value.set(Math.round(camera.position.x/2)*2,Math.round(camera.position.z/2)*2);}};
}
